helper='lem-dj-bridge-parabolic-double-coset-annihilation'
helperitem={'id':helper,'kind':'lemma','title':'Row symmetrizers and signed column symmetrizers vanish outside dominance','deps':['def-dj-bridge-row-column-permutation-modules-and-polytabloids','lem-dj-bridge-row-permutation-module-standard-action','lem-dj-bridge-sign-automorphism-and-star-dual'],'statement':r'For every commutative ring $R$, unit $q$ and partitions $\alpha,\nu\vdash n$, if $\alpha$ is not dominated by $\nu\prime$, then $x_\alpha H y_\nu=0$. The vanishing is a universal Laurent-polynomial identity, remains valid at singular parameters and uses no cancellation of $q+1$. The proof explicitly sorts parabolic double cosets and uses the zero product $(1+T_i)(1-q^{-1}T_i)=0$. Empty shapes and $n=0,1$ are included. No choice principle is used.','strategy':proofs['constructive-proof.md'].split('## 1. Opposite dominance annihilation, with no cancellation')[1].split('## 2. Signed cell quotient supplies spanning')[0].strip(),'provenance':{'statement':'literature-derived','proof':'ai-altered'},'sources':copy.deepcopy(items['def-dj-bridge-row-column-permutation-modules-and-polytabloids']['sources'])}
